export const TIMEZONE='America/Sao_Paulo';
export function dateKey(now=new Date()){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:TIMEZONE,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);const pick=t=>parts.find(p=>p.type===t).value;return pick('year')+'-'+pick('month')+'-'+pick('day');}
export function isUnlocked(event,now=new Date()){return now.getTime()>=openingTime(event);}
export function openingTime(event){const item=typeof event==='string'?(events.find(e=>e.date===event)??{date:event}):event;return new Date((item.releaseDate??item.date)+'T'+(item.time??'00:00')+':00-03:00').getTime();}
export function nextSurprise(events,now=new Date()){return events.find(e=>!isUnlocked(e,now))??null;}
